param([Parameter(Mandatory=$true)][ValidateSet('stage','test')][string]$Action)
$ErrorActionPreference='Stop';$ProgressPreference='SilentlyContinue';[Console]::OutputEncoding=[Text.UTF8Encoding]::new($false)
if(-not [Environment]::MachineName.Equals('baiying',[StringComparison]::OrdinalIgnoreCase)){throw 'Requires baiying'}
$sourcePath='D:\projects\cold-tail-package-source-r1.json';$m=[IO.File]::ReadAllText($sourcePath)|ConvertFrom-Json
function Verify-File([string]$Path,[string]$Sha){if((Get-FileHash -LiteralPath $Path -Algorithm SHA256).Hash.ToLowerInvariant() -ne $Sha){throw ('Changed input: '+$Path)}}
Verify-File $PSCommandPath $m.script_sha256
function Run-Git([string[]]$GitArguments){
 $psi=New-Object Diagnostics.ProcessStartInfo
 $psi.FileName='git.exe';$psi.UseShellExecute=$false;$psi.RedirectStandardOutput=$true;$psi.RedirectStandardError=$true
 $psi.Arguments=($GitArguments|ForEach-Object {'"'+$_.Replace('"','\"')+'"'}) -join ' '
 $p=New-Object Diagnostics.Process;$p.StartInfo=$psi
 if(-not $p.Start()){throw 'Git did not start'}
 $outTask=$p.StandardOutput.ReadToEndAsync();$errTask=$p.StandardError.ReadToEndAsync()
 if(-not $p.WaitForExit(30000)){try{$p.Kill()}catch{};throw 'Git timeout'}
 $stdout=$outTask.GetAwaiter().GetResult();$stderr=$errTask.GetAwaiter().GetResult()
 if($p.ExitCode -ne 0){throw ('Git failed: '+$stderr)}
 return $stdout.Trim()
}
$repo=$m.repo.Replace('/','\');$sha=$m.source_commit
$head=Run-Git -GitArguments @('-C',$repo,'rev-parse','HEAD')
$dirty=Run-Git -GitArguments @('-C',$repo,'status','--porcelain')
if($head -ne $sha -or $dirty){throw 'Source mismatch'}
$prior=[IO.File]::ReadAllText((Join-Path $repo 'build\cold-prefill-tail-build-r1\run-record.json'))|ConvertFrom-Json
if($prior.reason -ne 'completed' -or $prior.exit_code -ne 0 -or -not $prior.host_checks_pass){throw 'Same-source whole/CLI/probe build must complete'}
$env:PATH='C:\Program Files\AMD\ROCm\7.1\bin;'+$env:PATH
$out=Join-Path $repo ('build\cold-tail-package-'+$Action+'-r1');$specPath=$out+'.json'
foreach($p in @($out,$specPath)){if(Test-Path $p){throw ('Existing evidence: '+$p)}}
$spec=[ordered]@{executable='C:\Program Files\Python313\python.exe';working_directory=$repo;repo_commit=$sha;command_file=$PSCommandPath;command_file_sha256=$m.script_sha256;source_manifest_sha256=(Get-FileHash $sourcePath -Algorithm SHA256).Hash.ToLowerInvariant();model='D:/models/Qwen3.6-35B-A3B';inference_acceptance=$false;purpose='Actual relocated candidate with six pinned current components and a535-option portable long-context profile. Six binaries and runtime.env are replaced and the square-root table is added to268 verified base runtime assets. Original GB10 outputs/logits and actual streaming remain required. No publication or performance acceptance.'}
if($Action -eq 'stage'){
    $command=Join-Path 'D:\projects' $m.worker;Verify-File $command $m.worker_sha256
    $spec.arguments=@($command);$spec.model='none; stage verified runtime and CPU preflight';$spec.model_loaded=$false;$timeout=360
}else{
    $command=Join-Path $repo 'scripts\verify_baiying_q8192_http.py';Verify-File $command $m.http_script_sha256
    $config=Join-Path $repo 'build\cold-tail-package-http-config-r1.json'
    $spec.config_sha256=(Get-FileHash $config -Algorithm SHA256).Hash.ToLowerInvariant()
    $spec.arguments=@($command,'--execute','--config',$config,'--out',(Join-Path $repo 'build\cold-tail-package-requests-r1'));$timeout=420
}
$spec.controller_file=$command;$spec.controller_sha256=(Get-FileHash $command -Algorithm SHA256).Hash.ToLowerInvariant()
[IO.File]::WriteAllText($specPath,($spec|ConvertTo-Json -Depth 8),[Text.UTF8Encoding]::new($false))
& (Join-Path $repo 'scripts\baiying_guarded_inference.ps1') -SpecPath $specPath -OutDir $out -TimeoutSeconds $timeout|Out-Null
$r=[IO.File]::ReadAllText((Join-Path $out 'run-record.json'))|ConvertFrom-Json
$r|Select-Object reason,exit_code,wall_ms,host_checks_pass|ConvertTo-Json
if($r.reason -ne 'completed' -or $r.exit_code -ne 0 -or -not $r.host_checks_pass){throw ('HTTP '+$Action+' failed')}
